/* ============================================================
   StayQuest Design System
   Brand: Professional, Modern, Warm
   Colors: OKLCH — primary navy, accent blue, highlight gold
   Typography: Inter (Google Fonts)
   ============================================================ */

/* --- Google Fonts --- */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

/* --- Custom Properties --- */
:root {
  /* Brand palette */
  --primary:       oklch(32% 0.14 260);
  --primary-hover: oklch(36% 0.15 260);
  --primary-light: oklch(94% 0.03 260);
  --accent:        oklch(54% 0.19 260);
  --accent-hover:  oklch(58% 0.20 260);
  --gold:          oklch(82% 0.17 85);
  --gold-hover:    oklch(78% 0.18 85);
  --gold-subtle:   oklch(96% 0.04 85);

  /* Text */
  --text-primary:   oklch(20% 0.02 260);
  --text-secondary: oklch(40% 0.02 260);
  --text-muted:     oklch(58% 0.01 260);
  --text-on-primary: oklch(99% 0.005 260);
  --text-link:      oklch(54% 0.19 260);

  /* Backgrounds */
  --bg-primary: oklch(99%  0.002 260);
  --bg-surface: oklch(97%  0.004 260);
  --bg-card:    oklch(100% 0     0);

  /* Borders */
  --border:       oklch(88% 0.01 260);
  --border-light: oklch(94% 0.005 260);

  /* Rating colors */
  --rating-blue:  oklch(54% 0.19 260);
  --rating-gold:  oklch(82% 0.17 85);

  /* Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm:  0 1px 2px oklch(0% 0 0 / 0.06);
  --shadow-md:  0 4px 12px oklch(0% 0 0 / 0.08);
  --shadow-lg:  0 8px 24px oklch(0% 0 0 / 0.10);
  --shadow-xl:  0 16px 48px oklch(0% 0 0 / 0.12);

  /* Typography */
  --font-sans: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
  --fs-xs:   0.75rem;
  --fs-sm:   0.8125rem;
  --fs-base: 0.875rem;
  --fs-md:   1rem;
  --fs-lg:   1.125rem;
  --fs-xl:   1.25rem;
  --fs-2xl:  1.5rem;
  --fs-3xl:  2rem;
  --fs-4xl:  2.5rem;
  --fs-5xl:  3rem;

  /* Spacing */
  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;
  --space-2xl: 48px;
  --space-3xl: 64px;
  --space-4xl: 96px;

  /* Layout */
  --max-width: 1200px;
  --nav-height: 64px;
}

/* --- Reset --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-sans);
  font-size: var(--fs-base);
  line-height: 1.5;
  color: var(--text-primary);
  background: var(--bg-primary);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
button { font: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }
input, select, textarea { font: inherit; }

/* --- Utilities --- */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.sr-only {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); border: 0;
}

.section {
  padding: var(--space-3xl) 0;
}

.section-head {
  margin-bottom: var(--space-xl);
}

.section-head h2 {
  font-size: var(--fs-2xl);
  font-weight: 800;
  color: var(--text-primary);
  margin-bottom: var(--space-xs);
}

.section-head p {
  font-size: var(--fs-md);
  color: var(--text-secondary);
}

/* --- Navigation --- */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--primary);
  color: var(--text-on-primary);
}

.nav-inner {
  display: flex;
  align-items: center;
  height: var(--nav-height);
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
  gap: var(--space-xl);
}

.nav-logo {
  font-size: var(--fs-xl);
  font-weight: 800;
  letter-spacing: -0.5px;
  white-space: nowrap;
  color: #fff;
  flex-shrink: 0;
}

.nav-logo span {
  color: var(--gold);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  overflow-x: auto;
}

.nav-links a {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  padding: var(--space-sm) var(--space-md);
  border-radius: var(--radius-full);
  font-size: var(--fs-sm);
  font-weight: 500;
  white-space: nowrap;
  color: oklch(92% 0.01 260);
  transition: background 0.2s, color 0.2s;
}

.nav-links a:hover {
  background: oklch(40% 0.14 260);
  color: #fff;
}

.nav-links a.active {
  background: oklch(45% 0.15 260);
  color: #fff;
}

.nav-links a svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}

.nav-hamburger {
  display: none;
  padding: var(--space-sm);
  color: #fff;
}

.mobile-nav {
  display: none;
  position: fixed;
  top: var(--nav-height);
  left: 0; right: 0; bottom: 0;
  background: var(--primary);
  z-index: 99;
  padding: var(--space-lg);
  flex-direction: column;
  gap: var(--space-sm);
}

.mobile-nav.open {
  display: flex;
}

.mobile-nav a {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  padding: var(--space-md);
  border-radius: var(--radius-md);
  font-size: var(--fs-md);
  font-weight: 500;
  color: oklch(92% 0.01 260);
}

.mobile-nav a:hover,
.mobile-nav a.active {
  background: oklch(40% 0.14 260);
  color: #fff;
}

/* --- Hero --- */
.hero {
  background: var(--primary);
  color: var(--text-on-primary);
  padding: var(--space-2xl) 0 var(--space-3xl);
  position: relative;
  overflow: hidden;
}

.hero::after {
  content: '';
  position: absolute;
  bottom: 0; left: 0; right: 0;
  height: 40px;
  background: var(--bg-primary);
  border-radius: var(--radius-xl) var(--radius-xl) 0 0;
}

.hero-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
  position: relative;
  z-index: 1;
}

.hero h1 {
  font-size: var(--fs-4xl);
  font-weight: 800;
  line-height: 1.15;
  margin-bottom: var(--space-sm);
  max-width: 600px;
}

.hero .subtitle {
  font-size: var(--fs-lg);
  color: oklch(88% 0.02 260);
  margin-bottom: var(--space-xl);
  max-width: 500px;
}

/* --- Search Form --- */
.search-form {
  background: var(--gold);
  border-radius: var(--radius-lg);
  padding: var(--space-md);
  display: flex;
  gap: var(--space-sm);
  align-items: flex-end;
  flex-wrap: wrap;
  box-shadow: var(--shadow-lg);
  max-width: 900px;
}

.search-form .field {
  flex: 1 1 180px;
  min-width: 0;
}

.search-form .field.narrow {
  flex: 0 0 auto;
}

.search-form label {
  display: block;
  font-size: var(--fs-xs);
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: var(--space-xs);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.search-form input,
.search-form select {
  width: 100%;
  padding: var(--space-sm) var(--space-md);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-card);
  font-size: var(--fs-sm);
  color: var(--text-primary);
  transition: border-color 0.2s;
}

.search-form input:focus,
.search-form select:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px oklch(54% 0.19 260 / 0.15);
}

.search-form .btn-search {
  padding: var(--space-sm) var(--space-xl);
  background: var(--primary);
  color: #fff;
  font-weight: 700;
  font-size: var(--fs-md);
  border-radius: var(--radius-sm);
  white-space: nowrap;
  transition: background 0.2s;
  flex-shrink: 0;
}

.search-form .btn-search:hover {
  background: var(--primary-hover);
}

.search-extras {
  margin-top: var(--space-md);
  display: flex;
  gap: var(--space-lg);
  flex-wrap: wrap;
}

.search-extras label {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-size: var(--fs-sm);
  color: oklch(90% 0.01 260);
  cursor: pointer;
}

.search-extras input[type="checkbox"] {
  width: 16px;
  height: 16px;
  accent-color: var(--gold);
}

/* Package radio buttons */
.radio-group {
  display: flex;
  gap: var(--space-sm);
  flex-wrap: wrap;
}

.radio-group label {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  padding: var(--space-sm) var(--space-md);
  background: var(--bg-card);
  border: 2px solid var(--border);
  border-radius: var(--radius-full);
  font-size: var(--fs-sm);
  font-weight: 500;
  color: var(--text-primary);
  cursor: pointer;
  transition: border-color 0.2s, background 0.2s;
  text-transform: none;
  letter-spacing: normal;
}

.radio-group input[type="radio"] {
  width: 14px;
  height: 14px;
  accent-color: var(--accent);
}

.radio-group input[type="radio"]:checked + span {
  color: var(--accent);
  font-weight: 600;
}

.radio-group label:has(input:checked) {
  border-color: var(--accent);
  background: oklch(95% 0.03 260);
}

/* --- Trust Badges --- */
.trust-badges {
  padding: var(--space-xl) 0;
  border-bottom: 1px solid var(--border-light);
}

.trust-bades-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-lg);
}

.trust-badge {
  display: flex;
  align-items: flex-start;
  gap: var(--space-md);
}

.trust-badge-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  background: var(--primary-light);
  color: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.trust-badge-icon svg {
  width: 20px;
  height: 20px;
}

.trust-badge h4 {
  font-size: var(--fs-sm);
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 2px;
}

.trust-badge p {
  font-size: var(--fs-xs);
  color: var(--text-muted);
  line-height: 1.4;
}

/* --- Offers --- */
.offers-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-lg);
}

.offer-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  min-height: 240px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: var(--space-xl);
  color: #fff;
}

.offer-card.getaway {
  background: linear-gradient(135deg, oklch(45% 0.16 260), oklch(30% 0.14 260));
}

.offer-card.credit {
  background: linear-gradient(135deg, oklch(55% 0.18 260), oklch(40% 0.16 260));
}

.offer-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: oklch(0% 0 0 / 0.2);
  z-index: 0;
}

.offer-card > * {
  position: relative;
  z-index: 1;
}

.offer-card h3 {
  font-size: var(--fs-xl);
  font-weight: 800;
  margin-bottom: var(--space-sm);
  line-height: 1.2;
}

.offer-card p {
  font-size: var(--fs-sm);
  color: oklch(92% 0.01 260);
  margin-bottom: var(--space-md);
  line-height: 1.5;
}

.offer-card .btn-offer {
  display: inline-block;
  padding: var(--space-sm) var(--space-lg);
  background: #fff;
  color: var(--primary);
  font-weight: 700;
  font-size: var(--fs-sm);
  border-radius: var(--radius-sm);
  transition: background 0.2s;
}

.offer-card .btn-offer:hover {
  background: oklch(95% 0.01 260);
}

/* --- Property Types --- */
.property-types {
  padding: var(--space-2xl) 0;
  border-bottom: 1px solid var(--border-light);
}

.property-types h2 {
  font-size: var(--fs-xl);
  font-weight: 800;
  margin-bottom: var(--space-md);
}

.property-chips {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
}

.property-chip {
  padding: var(--space-sm) var(--space-md);
  border: 1px solid var(--border);
  border-radius: var(--radius-full);
  font-size: var(--fs-sm);
  color: var(--text-secondary);
  transition: all 0.2s;
  cursor: pointer;
}

.property-chip:hover {
  border-color: var(--accent);
  color: var(--accent);
  background: oklch(97% 0.03 260);
}

/* --- Tabs --- */
.tabs {
  display: flex;
  gap: var(--space-xs);
  overflow-x: auto;
  padding-bottom: var(--space-sm);
  margin-bottom: var(--space-lg);
  -webkit-overflow-scrolling: touch;
}

.tabs::-webkit-scrollbar {
  height: 2px;
}

.tabs::-webkit-scrollbar-thumb {
  background: var(--border);
  border-radius: var(--radius-full);
}

.tab-btn {
  padding: var(--space-sm) var(--space-md);
  border-radius: var(--radius-full);
  font-size: var(--fs-sm);
  font-weight: 500;
  color: var(--text-secondary);
  white-space: nowrap;
  border: 1px solid var(--border);
  transition: all 0.2s;
  background: var(--bg-card);
}

.tab-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.tab-btn.active {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.tab-panel {
  display: none;
}

.tab-panel.active {
  display: block;
}

/* --- Trip Planner --- */
.trip-destinations {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: var(--space-md);
}

.trip-dest-card {
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  padding: var(--space-md);
  text-align: center;
  transition: box-shadow 0.2s, border-color 0.2s;
  cursor: pointer;
}

.trip-dest-card:hover {
  border-color: var(--accent);
  box-shadow: var(--shadow-md);
}

.trip-dest-card .dest-img {
  width: 100%;
  aspect-ratio: 4/3;
  border-radius: var(--radius-sm);
  background: var(--bg-surface);
  margin-bottom: var(--space-sm);
  object-fit: cover;
  background: linear-gradient(135deg, oklch(80% 0.06 200), oklch(70% 0.08 260));
}

.trip-dest-card h4 {
  font-size: var(--fs-sm);
  font-weight: 600;
}

.trip-dest-card span {
  font-size: var(--fs-xs);
  color: var(--text-muted);
}

/* --- Carousel --- */
.carousel-wrapper {
  position: relative;
}

.carousel-track {
  display: flex;
  gap: var(--space-md);
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: var(--space-sm) 0;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-60%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--bg-card);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  transition: all 0.2s;
}

.carousel-arrow:hover {
  background: var(--bg-surface);
  box-shadow: var(--shadow-lg);
}

.carousel-arrow.prev { left: -12px; }
.carousel-arrow.next { right: -12px; }

.carousel-arrow svg {
  width: 18px;
  height: 18px;
  color: var(--text-primary);
}

/* --- Property Card --- */
.prop-card {
  flex: 0 0 260px;
  scroll-snap-align: start;
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: box-shadow 0.2s;
}

.prop-card:hover {
  box-shadow: var(--shadow-lg);
}

.prop-card-img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  background: linear-gradient(135deg, oklch(75% 0.06 200), oklch(65% 0.08 260));
}

.prop-card-body {
  padding: var(--space-md);
}

.prop-card-body h4 {
  font-size: var(--fs-sm);
  font-weight: 600;
  margin-bottom: 2px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.prop-card-body .location {
  font-size: var(--fs-xs);
  color: var(--text-muted);
  margin-bottom: var(--space-sm);
}

.prop-card-body .rating-row {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  margin-bottom: var(--space-sm);
}

.rating-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--primary);
  color: #fff;
  font-size: var(--fs-xs);
  font-weight: 700;
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  min-width: 28px;
}

.rating-label {
  font-size: var(--fs-xs);
  font-weight: 600;
  color: var(--text-primary);
}

.review-count {
  font-size: var(--fs-xs);
  color: var(--text-muted);
}

.prop-card-body .price-row {
  display: flex;
  align-items: baseline;
  gap: var(--space-sm);
}

.price-original {
  font-size: var(--fs-sm);
  color: var(--text-muted);
  text-decoration: line-through;
}

.price-current {
  font-size: var(--fs-lg);
  font-weight: 800;
  color: var(--text-primary);
}

.price-duration {
  font-size: var(--fs-xs);
  color: var(--text-muted);
}

/* --- Trending Destinations --- */
.trending-grid {
  display: flex;
  gap: var(--space-md);
  overflow-x: auto;
  padding-bottom: var(--space-sm);
  scrollbar-width: none;
}

.trending-grid::-webkit-scrollbar { display: none; }

.trending-card {
  flex: 0 0 200px;
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  cursor: pointer;
}

.trending-card img {
  width: 100%;
  aspect-ratio: 3/4;
  object-fit: cover;
  background: linear-gradient(135deg, oklch(70% 0.08 200), oklch(60% 0.10 260));
}

.trending-card .overlay {
  position: absolute;
  bottom: 0;
  left: 0; right: 0;
  padding: var(--space-md);
  background: linear-gradient(transparent, oklch(0% 0 0 / 0.6));
  color: #fff;
}

.trending-card .overlay h4 {
  font-size: var(--fs-md);
  font-weight: 700;
}

/* --- Explore Destinations Grid --- */
.dest-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: var(--space-md);
}

.dest-card {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  padding: var(--space-md);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.dest-card:hover {
  border-color: var(--accent);
  box-shadow: var(--shadow-sm);
}

.dest-card-img {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-md);
  object-fit: cover;
  background: linear-gradient(135deg, oklch(75% 0.06 200), oklch(65% 0.08 260));
  flex-shrink: 0;
}

.dest-card-info h4 {
  font-size: var(--fs-sm);
  font-weight: 600;
}

.dest-card-info span {
  font-size: var(--fs-xs);
  color: var(--text-muted);
}

/* --- Weekend Deals --- */
.deals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: var(--space-md);
}

.deal-card {
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: box-shadow 0.2s;
}

.deal-card:hover {
  box-shadow: var(--shadow-lg);
}

.deal-card-img {
  width: 100%;
  aspect-ratio: 16/10;
  object-fit: cover;
  background: linear-gradient(135deg, oklch(75% 0.06 200), oklch(65% 0.08 260));
  position: relative;
}

.deal-badge {
  position: absolute;
  top: var(--space-sm);
  left: var(--space-sm);
  background: var(--gold);
  color: var(--text-primary);
  font-size: var(--fs-xs);
  font-weight: 700;
