cd /app/output && for f in *.html; do echo "=== $f ===" && python3 -c "
from html.parser import HTMLParser
import sys

class Validator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.void_elements = {'area','base','br','col','embed','hr','img','input','link','meta','source','track','wbr'}
        self.errors = []
    def handle_starttag(self, tag, attrs):
        if tag not in self.void_elements:
            self.stack.append((tag, self.getpos()))
    def handle_endtag(self, tag):
        if tag in self.void_elements:
            return
        if self.stack and self.stack[-1][0] == tag:
            self.stack.pop()
        elif self.stack:
            self.errors.append(f'Mismatched: </{tag}> at line {self.getpos()[0]}, expected </{self.stack[-1][0]}>')
        else:
            self.errors.append(f'Extra closing: </{tag}> at line {self.getpos()[0]}')

v = Validator()
with open('$f') as fh:
    v.feed(fh.read())
if v.errors:
    for e in v.errors[:5]:
        print(e)
elif v.stack:
    print(f'Unclosed tags: {[t[0] for t in v.stack]}')
else:
    print('OK')
" 2>&1; done

